   --bubble-me-padding: 10px 12px;
   --bubble-me-radius: 4px;
   --bubble-me-shadow: none;
   --bubble-me-border: none;
   --bubble-me-link-color: transparent;

   /* === 对方气泡 === */
   --bubble-them-bg: #FFF;
   --bubble-them-bg-gradient: initial;
   --bubble-them-color: #000;
   --bubble-them-line-height: 1.2;
   --bubble-them-padding: 10px 12px;
   --bubble-them-radius: 4px;
   --bubble-them-shadow: none;
   --bubble-them-border: none;
   --bubble-them-link-color: transparent;

   /* === 语音 === */
   --voice-transcription-color: #6E6E6E;
   --voice-transcription-bg: transparent;
  /* —— 容器布局 —— */
   --voice-container-gap: 3px;
   --voice-controls-gap: 0px;
  /* —— 播放按钮 —— */
   --voice-play-btn-size: 24px;
   --voice-play-btn-bg: transparent;
   --voice-btn: url("https://i.postimg.cc/kXymFms9/wu-biao-ti161-20260515061153.png");
   --voice-play-btn-border: none;
   --voice-play-btn-radius: 50%;
   --voice-play-btn-shadow: none;
   --voice-play-btn-opacity: 1;
  /* —— 波形 —— */
   --voice-waveform-height: 26px;
   --voice-waveform-gap: 2px;
   --voice-bar-min-width: 1px;
   --voice-bar-max-width: 2px;
   --voice-bar-radius: 12px;
  /* —— 时间戳 —— */
   --voice-duration-size: 11px;
   --voice-duration-weight: 600;
  /* —— 下载按钮（设 none 可隐藏） —— */
   --voice-download-display: flex;
   --voice-download-opacity: 0;

   --transfer-card-bg: #FA9D3B;
   --transfer-text-color: #FFF;
