  --transfer-icon-expired: url('https://nos.netease.com/ysf/dfbb30c0b7383f9209c03597b101adfe.png');

   /* === 输入区域 === */
   --input-area-bg: #F8F8F8ED;
   --input-area-border-top: 1px solid #E8E8E8;
   --input-area-padding: 6px 7px 10px 7px;

   /* === 🍓底栏图标 === */
   --icon-img-1: url('https://i.postimg.cc/503ZwSqw/wu-biao-ti38-20260124015919.png'); /* 加号 */
   --icon-img-2: url('https://i.postimg.cc/rFspQMFN/wu-biao-ti161-20260514123227.png'); /* 麦克风 */
   --icon-img-3: url('https://i.postimg.cc/63yswvN5/wu-biao-ti38-20260128163919.png'); /* 贴纸 */
   --icon-img-4: url('https://i.postimg.cc/ZRc1rxF8/wu-biao-ti38-20260124014355.png'); /* AI */

   /* === 输入框 === */
   --input-box-bg: #FFFFFF;
   --input-box-color: #000;
   --input-box-radius: 6px;
   --input-box-padding: 7px 2px;
   --input-box-placeholder: transparent;
